    float halo = soft(r, 15.0 * power) * 0.065;
    float point = soft(r, 2.8 * power) * 0.6;
    energy += vec3(0.18, 0.025, 0.72) * (wisps * 0.65 + halo) + vec3(0.5, 0.26, 1.0) * point;
  }
  float coverage = max(energy.r, max(energy.g, energy.b));
  return vec4(energy / max(0.0001, coverage), sat(coverage));
