  vec2 edge = smoothstep(vec2(0.0), vec2(8.0), margin);
  result.a *= edge.x * edge.y * color.a;
  if (fxState.w >= 1.5) return vec4(result.rgb * result.a * color.rgb, result.a);
  return vec4(result.rgb * color.rgb, result.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

